            <td class="px-5 py-4"><?php if ($genderLabel !== null): ?><span class="inline-flex rounded-full px-2.5 py-1 text-xs font-semibold <?= $genderClass ?>"><?= e(t($genderLabel)) ?></span><?php else: ?><span class="text-zinc-400">—</span><?php endif; ?></td>
            <td class="px-5 py-4"><?php if (!empty($person['profile'])): ?><img src="<?= e($person['profile']) ?>" alt="<?= e(t('{name} profile image', ['name' => $person['full_name']])) ?>" loading="lazy" class="size-10 rounded-full border border-zinc-200 object-cover dark:border-zinc-700"><?php else: ?><span class="grid size-10 place-items-center rounded-full bg-violet-100 text-violet-700 dark:bg-violet-950 dark:text-violet-300" role="img" aria-label="<?= e(t('No profile image')) ?>"><svg class="size-5" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="12" cy="8" r="3.5"/><path stroke-linecap="round" stroke-linejoin="round" d="M5 20c.5-3.8 3.1-5.8 7-5.8s6.5 2 7 5.8"/></svg></span><?php endif; ?></td>
            <td class="px-5 py-4"><?= e($person['username']) ?></td>
