            <td class="px-5 py-4"><span class="rounded-full bg-violet-50 px-2.5 py-1 text-xs font-semibold capitalize text-primary dark:bg-violet-950/50 dark:text-violet-300"><?= e(t(ucfirst($person['role']))) ?></span></td>
            <td class="px-5 py-4"><span class="rounded-full px-2.5 py-1 text-xs font-semibold <?= (int)$person['is_active']===1?'bg-green-50 text-green-700 dark:bg-green-950 dark:text-green-300':'bg-zinc-100 text-zinc-600 dark:bg-zinc-800 dark:text-zinc-300' ?>"><?= e(t((int)$person['is_active']===1?'Active':'Disabled')) ?></span></td>
            <td class="px-5 py-4"><div class="flex justify-end gap-2"><a href="/users/<?= (int)$person['id'] ?>/edit" class="rounded-md border border-zinc-200 px-3 py-1.5 text-xs font-semibold hover:border-primary hover:text-primary dark:border-zinc-700"><?= e(t('Edit')) ?></a><?php if($person['role']!=='admin'): ?><a href="/users/<?= (int)$person['id'] ?>/permissions" class="rounded-md border border-zinc-200 px-3 py-1.5 text-xs font-semibold hover:border-primary hover:text-primary dark:border-zinc-700"><?= e(t('Permissions')) ?></a><?php endif; ?><a href="/users/<?= (int)$person['id'] ?>/reset-password" class="rounded-md border border-zinc-200 px-3 py-1.5 text-xs font-semibold hover:border-primary hover:text-primary dark:border-zinc-700"><?= e(t('Reset password')) ?></a><form method="post" action="/users/<?= (int)$person['id'] ?>/status"><input type="hidden" name="_csrf_token" value="<?= e($csrfToken) ?>"><button class="rounded-md <?= (int)$person['is_active']===1?'bg-red-50 text-red-700 hover:bg-red-100 dark:bg-red-950 dark:text-red-300':'bg-green-50 text-green-700 hover:bg-green-100 dark:bg-green-950 dark:text-green-300' ?> px-3 py-1.5 text-xs font-semibold" type="submit"><?= e(t((int)$person['is_active']===1?'Disable':'Enable')) ?></button></form></div></td>
        </tr>
    <?php endforeach; ?>
    <?php if($users===[]): ?><tr><td colspan="8" class="px-5 py-12 text-center text-zinc-500"><?= e(t('No user accounts found.')) ?></td></tr><?php endif; ?></tbody></table></div></article>
